def compute(vars):
    total_maturity = vars["v1"]
    euro_maturity = vars["v2"]
    value = total_maturity - euro_maturity
    return {
        "value": value,
        "trace": {
            "total_maturity": total_maturity,
            "euro_maturity": euro_maturity,
            "output_meta": {
                "currency": "USD",
                "scale": "million",
                "unit": None
            }
        }
    }
